299: 
300: /* ---------- buttons ---------- */
301: .pbtn {
302:   font-family: 'PixelTitle', monospace;
303:   font-size: 10px;
304:   letter-spacing: 1px;
305:   color: #fdfbf3;
306:   background: linear-gradient(180deg, #2a3568 0%, #1a2247 60%, #131a38 100%);
307:   border: 2px solid #7e8bc4;
308:   border-radius: 9px;
309:   padding: 13px 18px 12px;
310:   box-shadow: 0 4px 0 #060811, inset 0 1px 0 rgba(255,255,255,.16);
311:   cursor: pointer;
312:   transition: transform .08s, box-shadow .08s, filter .12s;
313:   text-shadow: 0 2px 0 #000;
314:   position: relative;
315: }
316: .pbtn:hover { filter: brightness(1.18); transform: translateY(-1px); }
317: .pbtn:active { transform: translateY(3px); box-shadow: 0 1px 0 #060811, inset 0 1px 0 rgba(255,255,255,.1); }
318: .pbtn.gold {
319:   color: #241802;
320:   background: linear-gradient(180deg, #ffe89a 0%, #f5c542 55%, #d99b1e 100%);
321:   border-color: #fff0b8;
322:   text-shadow: 0 1px 0 rgba(255,255,255,.5);
323:   box-shadow: 0 4px 0 #6b3e0a, inset 0 1px 0 rgba(255,255,255,.5);
324: }
325: .pbtn.gold:active { box-shadow: 0 1px 0 #6b3e0a; }
326: .pbtn.small { font-size: 8px; padding: 9px 12px 8px; }
327: .pbtn.danger { border-color: #b45a6a; background: linear-gradient(180deg,#4a2230,#2a1018); }
328: .pbtn:disabled { filter: grayscale(.7) brightness(.7); cursor: not-allowed; transform: none; }
