331: .screen {
332:   position: absolute;
333:   inset: 0;
334:   background:
335:     radial-gradient(800px 500px at 50% 0%, rgba(64,84,160,.28), transparent 65%),
336:     linear-gradient(180deg, rgba(8,11,24,.96), rgba(5,7,14,.985));
