443: .party-card:hover { border-color: #6f86d6; transform: translateY(-1px); }
444: .party-card.active { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(245,197,66,.25); }
445: .party-card.fainted { opacity: .55; }
446: .pc-sprite { width: 74px; height: 74px; flex: 0 0 74px; image-rendering: pixelated; align-self: center; }
447: .pc-info { flex: 1; min-width: 0; }
448: .pc-top { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
449: .pc-name { font-family: 'PixelTitle'; font-size: 9px; color: #fff; text-shadow: 0 2px 0 #000; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
450: .pc-lv { font-family: 'PixelTitle'; font-size: 8px; color: var(--gold); }
451: .pc-types { display: flex; gap: 5px; margin: 6px 0 5px; }
452: .tchip { font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px 2px; border-radius: 4px; color: #05060c; letter-spacing: .3px; }
453: .pc-hp { font-family: 'PixelBody'; font-size: 17px; color: #cdd6f4; display: flex; justify-content: space-between; }
