459: .pc-xp .bar { height: 4px; }
460: .pc-xp .bar > i { background: linear-gradient(90deg, #67e8f9, #9b7bff); }
461: .pc-tag { position: absolute; right: 8px; bottom: 8px; font-family: 'PixelTitle'; font-size: 6px; color: #93a4d8; }
462: .pc-soul { position: absolute; left: -2px; top: -2px; background: var(--violet); color: #fff; font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px; border-radius: 5px; box-shadow: 0 0 12px rgba(155,123,255,.8); }
463: 
464: .tabbar { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
465: .tab {
466:   font-family: 'PixelTitle'; font-size: 8px; color: #aab6dd; background: #111731;
467:   border: 2px solid #2b3762; border-radius: 8px; padding: 10px 14px; cursor: pointer;
468: }
469: .tab.on { color: #1b1403; background: linear-gradient(180deg,#ffe9a0,#f5c542); border-color: #fff0b8; }
470: .item-list { display: flex; flex-direction: column; gap: 8px; }
471: .item-row {
472:   display: flex; align-items: center; gap: 12px; background: linear-gradient(180deg,#161e3d,#0f142b);
