477: .item-name { flex: 1; font-family: 'PixelTitle'; font-size: 9px; }
478: .item-desc { font-size: 20px; color: #aeb9dd; line-height: 1; margin-top: 4px; font-family: 'PixelBody'; }
479: .item-qty { font-family: 'PixelTitle'; font-size: 9px; color: var(--gold); }
480: .empty { color: #6b789f; font-size: 26px; text-align: center; padding: 50px 20px; }
481: 
482: /* ---------- shop / dialogs ---------- */
483: .modal-center {
484:   position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; z-index: 40;
485:   background: rgba(3,5,12,.72); backdrop-filter: blur(2px);
486: }
487: .modal {
488:   width: min(620px, 88%);
489:   background: linear-gradient(180deg, #182046, #0c1124);
490:   border: 3px solid #e8d9a0;
491:   border-radius: 14px;
492:   box-shadow: 0 0 0 3px #141a33, 0 18px 50px rgba(0,0,0,.8);
493:   padding: 20px 22px;
494: }
495: .modal h3 { font-family: 'PixelTitle'; font-size: 13px; color: var(--gold); margin: 0 0 10px; letter-spacing: .5px; }
496: .modal p { font-size: 25px; color: #dce3f7; margin: 0 0 18px; line-height: 1.1; }
497: .modal .row { display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; }
498: .shop-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
499: .shop-item { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 2px solid #2c3868; border-radius: 9px; background: #111731; cursor: pointer; }
500: .shop-item:hover { border-color: var(--gold); }
501: .shop-item .n { flex: 1; font-family: 'PixelTitle'; font-size: 8px; }
502: .shop-item .p { font-family: 'PixelTitle'; font-size: 8px; color: var(--gold); }
503: 
504: /* ---------- choice menus ---------- */
505: .menu-window {
506:   position: absolute;
507:   top: 50%; left: 50%;
508:   transform: translate(-50%, -50%);
509:   width: min(560px, calc(100% - 32px));
510:   max-height: calc(100% - 32px);
511:   overflow: auto;
512:   padding: 22px 24px 18px;
513:   color: var(--text);
514:   background: linear-gradient(180deg, rgba(25,34,70,.98), rgba(9,13,29,.99));
515:   border: 3px solid #e8d9a0;
516:   border-radius: 14px;
517:   box-shadow: 0 0 0 3px #141a33, 0 18px 50px rgba(0,0,0,.8), 0 0 0 100vmax rgba(3,5,12,.66);
518: }
519: .menu-title {
520:   margin: 0 0 10px;
521:   color: var(--gold);
