30:   const speciesOf = mon => mon?.species || mon?.id || mon?.speciesId || '';
31:   const speciesData = mon => SPECIES[speciesOf(mon)] || {};
32:   const moveId = move => typeof move === 'string' ? move : move?.id || move?.move || '';
33:   const validMove = id => MOVES[id] || null;
34:   const cloneTeamEntry = entry => Array.isArray(entry)
35:     ? { species: entry[0], level: entry[1] }
