38:   function createMember(species, level = 5, options = {}) {
39:     const data = SPECIES[species];
40:     if (!data) throw new Error(`Unknown Pokémon species: ${species}`);
41:     const mon = {
42:       species, name: options.name || data.name, level: Math.max(1, number(level, 5)),
43:       xp: Math.max(0, number(options.xp, 0)), status: options.status || null,
44:       moves: (options.moves || data.moves || ['tackle']).slice(0, 4),
45:       maxHp: 1, hp: 1, stats: {},
46:       ...(options || {})
47:     };
48:     mon.species = species;
49:     mon.level = Math.max(1, Math.floor(number(mon.level, 5)));
50:     mon.moves = (Array.isArray(mon.moves) ? mon.moves : data.moves || ['tackle'])
51:       .map(moveId).filter(id => id && validMove(id)).slice(0, 4);
52:     if (!mon.moves.length) mon.moves = ['tackle'];
53:     refreshStats(mon, true);
54:     if (Number.isFinite(Number(options.maxHp))) mon.maxHp = Math.max(1, Number(options.maxHp));
55:     mon.hp = Math.max(0, Math.min(mon.maxHp, number(options.hp, mon.maxHp)));
56:     mon.status = options.status || null;
57:     mon.xp = Math.max(0, number(options.xp, mon.xp));
58:     mon.stages = mon.stages || {};
59:     mon.pp = mon.pp && typeof mon.pp === 'object' ? mon.pp : {};
60:     for (const id of mon.moves) {
