67:   function refreshStats(mon, preserveRatio = false) {
68:     const data = speciesData(mon);
69:     const base = Array.isArray(data.base) ? data.base : [45, 49, 49, 45, 65, 45];
70:     const level = Math.max(1, number(mon.level, 5));
71:     const oldMax = Math.max(1, number(mon.maxHp, 1));
72:     const oldHp = number(mon.hp, oldMax);
73:     const stats = {
74:       hp: Math.floor((2 * number(base[0], 45) * level) / 100) + level + 10,
75:       atk: Math.floor((2 * number(base[1], 49) * level) / 100) + 5,
76:       def: Math.floor((2 * number(base[2], 49) * level) / 100) + 5,
77:       spa: Math.floor((2 * number(base[3], 45) * level) / 100) + 5,
78:       spd: Math.floor((2 * number(base[4], 65) * level) / 100) + 5,
79:       spe: Math.floor((2 * number(base[5], 45) * level) / 100) + 5
80:     };
81:     mon.stats = stats;
82:     mon.maxHp = stats.hp;
83:     mon.hp = preserveRatio ? Math.max(0, Math.min(stats.hp, Math.round(oldHp / oldMax * stats.hp))) : stats.hp;
