84: const Sound = {
85:   ctx: null, master: null, musicGain: null, sfxGain: null,
86:   musicOn: true, sfxOn: true, track: null, loopTimer: null, noiseBuf: null, beat: 0,
87: 
88:   init() {
89:     if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
90:     const AC = window.AudioContext || window.webkitAudioContext;
91:     if (!AC) return;
92:     this.ctx = new AC();
93:     this.master = this.ctx.createGain(); this.master.gain.value = 0.55; this.master.connect(this.ctx.destination);
94:     this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = this.musicOn ? 0.34 : 0; this.musicGain.connect(this.master);
95:     this.sfxGain = this.ctx.createGain(); this.sfxGain.gain.value = this.sfxOn ? 0.5 : 0; this.sfxGain.connect(this.master);
96:     // noise buffer
97:     const len = this.ctx.sampleRate * 0.6;
98:     this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
99:     const d = this.noiseBuf.getChannelData(0);
100:     for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
101:   },
102:   setMusic(on) { this.musicOn = on; if (this.musicGain) this.musicGain.gain.setTargetAtTime(on ? 0.34 : 0, this.ctx.currentTime, .05); },
103:   setSfx(on) { this.sfxOn = on; if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(on ? 0.5 : 0, this.ctx.currentTime, .05); },
104:   note(freq, dur, type = 'square', vel = .2, when = 0, target = null, slide = 0) {
105:     if (!this.ctx) return;
106:     const t = this.ctx.currentTime + when;
107:     const o = this.ctx.createOscillator();
108:     const g = this.ctx.createGain();
109:     o.type = type; o.frequency.setValueAtTime(freq, t);
110:     if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
111:     g.gain.setValueAtTime(0.0001, t);
112:     g.gain.exponentialRampToValueAtTime(vel, t + 0.012);
113:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur * 1.55);
114:     o.connect(g); g.connect(target || this.musicGain);
115:     o.start(t); o.stop(t + dur * 1.7);
116:   },
117:   drum(when = 0, kind = 'kick', vel = .35) {
118:     if (!this.ctx) return;
119:     const t = this.ctx.currentTime + when;
120:     if (kind === 'kick') {
121:       const o = this.ctx.createOscillator(), g = this.ctx.createGain();
122:       o.type = 'sine'; o.frequency.setValueAtTime(130, t); o.frequency.exponentialRampToValueAtTime(38, t + .12);
123:       g.gain.setValueAtTime(vel, t); g.gain.exponentialRampToValueAtTime(0.001, t + .16);
124:       o.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + .18);
125:     } else {
126:       const s = this.ctx.createBufferSource(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter();
127:       s.buffer = this.noiseBuf; f.type = kind === 'hat' ? 'highpass' : 'bandpass'; f.frequency.value = kind === 'hat' ? 7500 : 1800;
128:       g.gain.setValueAtTime(vel, t); g.gain.exponentialRampToValueAtTime(0.001, t + (kind === 'hat' ? .05 : .12));
129:       s.connect(f); f.connect(g); g.connect(this.musicGain); s.start(t); s.stop(t + .14);
130:     }
131:   },
132:   midiFreq(m) { return 440 * Math.pow(2, (m - 69) / 12); },
133: 
134:   playTrack(name, opts = {}) {
135:     this.init();
136:     if (this.track === name && !opts.force) return;
137:     this.track = name;
138:     clearTimeout(this.loopTimer);
139:     if (!this.ctx) return;
140:     const tr = TRACKS[name] || TRACKS.town;
141:     this.beat = 0;
142:     const step = 60 / tr.bpm / 2;        // eighth-note
143:     const steps = tr.lead.length;
144:     const loopBeats = steps * step;
145: 
146:     const playLoop = () => {
147:       if (this.track !== name) return;
148:       const now = 0;
149:       // lead
150:       tr.lead.forEach((n, i) => {
151:         if (n === null || n === undefined) return;
152:         const f = this.midiFreq(tr.root + tr.scale[n % tr.scale.length] + 12 * Math.floor(n / tr.scale.length));
153:         this.note(f, step * 0.92, tr.leadWave || 'square', tr.leadVol || .16, i * step);
154:         if (tr.echo) this.note(f, step * .7, 'triangle', .05, i * step + step * 0.75);
155:       });
156:       // bass
157:       (tr.bass || []).forEach((n, i) => {
158:         if (n === null) return;
159:         const f = this.midiFreq(tr.root - 12 + tr.scale[n % tr.scale.length] + 12 * Math.floor(n / tr.scale.length));
160:         this.note(f, step * 1.8, 'triangle', .22, i * step * (tr.bassStep || 2));
161:       });
162:       // pad
163:       if (tr.pad) tr.pad.forEach((chord, i) => {
164:         chord.forEach(n => {
165:           const f = this.midiFreq(tr.root + tr.scale[0] + n);
166:           this.note(f, loopBeats / tr.pad.length * .95, 'sine', .055, i * loopBeats / tr.pad.length);
167:         });
168:       });
169:       // drums
170:       if (tr.drums) {
171:         for (let i = 0; i < steps; i++) {
172:           const d = tr.drums[i % tr.drums.length];
173:           if (d === 'k') this.drum(i * step, 'kick', .32);
174:           if (d === 's') this.drum(i * step, 'snare', .16);
175:           if (d === 'h') this.drum(i * step, 'hat', .07);
176:         }
177:       }
178:       this.loopTimer = setTimeout(playLoop, loopBeats * 1000 - 30);
179:     };
180:     playLoop();
181:   },
182:   stopMusic() { this.track = null; clearTimeout(this.loopTimer); },
183:   sfx(name) {
184:     this.init();
185:     if (!this.ctx || !this.sfxOn) return;
186:     const t = this.ctx.currentTime;
187:     const beep = (f, dur, type = 'square', vel = .16, when = 0, slide = 0) => this.note(f, dur, type, vel, when, this.sfxGain, slide);
188:     switch (name) {
189:       case 'blip': beep(760, .03, 'square', .06); break;
190:       case 'select': beep(520, .05, 'square', .12); beep(880, .07, 'square', .11, .05); break;
191:       case 'back': beep(420, .06, 'square', .1); beep(280, .07, 'square', .08, .05); break;
192:       case 'hit': this.drum(0, 'snare', .3); beep(180, .08, 'sawtooth', .16, 0, -80); break;
193:       case 'super': this.drum(0, 'snare', .4); beep(250, .12, 'sawtooth', .2, 0, -140); beep(120, .18, 'square', .15, .06, -60); break;
194:       case 'heal': [523,659,784,1047].forEach((f,i)=>beep(f,.16,'sine',.13,i*.09)); break;
195:       case 'ball': beep(300, .18, 'sine', .15, 0, 500); break;
196:       case 'catch': [523,659,784,1047,1319].forEach((f,i)=>beep(f,.18,'square',.12,i*.1)); break;
197:       case 'faint': beep(440, .5, 'square', .12, 0, -380); break;
198:       case 'level': [523,659,784,1047].forEach((f,i)=>beep(f,.14,'square',.15,i*.08)); break;
199:       case 'awaken': {
200:         const o = this.ctx.createOscillator(), g = this.ctx.createGain();
201:         o.type = 'sawtooth'; o.frequency.setValueAtTime(80, t); o.frequency.exponentialRampToValueAtTime(1400, t + .9);
202:         g.gain.setValueAtTime(.001, t); g.gain.exponentialRampToValueAtTime(.22, t + .2); g.gain.exponentialRampToValueAtTime(.001, t + 1.2);
203:         o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 1.3);
204:         [392,523,659,784,1047].forEach((f,i)=>beep(f,.4,'square',.1,.35+i*.09));
