284: function heldMovement(now) {
285:   if (titleActive || UI.active || Battle.busy || Game.state !== 'overworld') return;
286:   if (now - lastStep < 135) return;
287:   let dx = 0, dy = 0;
288:   if (Input.down('arrowup', 'w')) dy = -1;
289:   else if (Input.down('arrowdown', 's')) dy = 1;
290:   else if (Input.down('arrowleft', 'a')) dx = -1;
291:   else if (Input.down('arrowright', 'd')) dx = 1;
292:   if (dx || dy) { World.step(dx, dy); lastStep = now; }
293: }
