295: function loop(now) {
296:   requestAnimationFrame(loop);
297:   const dt = Math.min(100, now - (loop._last || now)); loop._last = now;
298:   try {
299:     heldMovement(now);
300:     if (titleActive) drawTitleFrame(now);
301:     else { World.update(dt); World.draw(); }
302:   } catch (error) {
303:     console.error('Frame error:', error);
304:   }
305: }
