30:     const p = BUILDING[o.type] || BUILDING.house;
31:     shadow(ctx, left + W / 2, top + H - 4, W * .47, 8, .32);
32: 
33:     // walls
34:     PX.rect(ctx, left + 4, top + 32, W - 8, H - 34, p.wallD);
35:     PX.rect(ctx, left + 6, top + 34, W - 12, H - 38, p.wall);
36:     PX.rect(ctx, left + 6, top + H - 16, W - 12, 12, p.wallD);
37:     PX.rect(ctx, left + 6, top + H - 18, W - 12, 2, p.trim);
38:     // siding
39:     for (let i = 0; i < 6; i++) PX.rect(ctx, left + 8, top + 38 + i * 8, W - 16, 1, rgba(p.wallD, .45));
40:     // corner trim
41:     PX.rect(ctx, left + 5, top + 30, 5, H - 32, p.trim);
42:     PX.rect(ctx, left + W - 10, top + 30, 5, H - 32, p.trim);
43: 
44:     // roof
45:     PX.tri(ctx, left - 8, top + 40, left + W / 2, top - 6, left + W + 8, top + 40, p.roofD);
46:     PX.tri(ctx, left + 2, top + 39, left + W / 2, top + 1, left + W - 2, top + 39, p.roof);
47:     PX.tri(ctx, left + 14, top + 36, left + W / 2 - 10, top + 8, left + W / 2 + 2, top + 12, p.roofL);
48:     PX.rect(ctx, left - 8, top + 39, W + 16, 4, p.roofD);
49:     PX.rect(ctx, left - 8, top + 39, W + 16, 1, p.roofL);
50:     // shingles
51:     for (let i = 0; i < 4; i++) {
52:       const yy = top + 16 + i * 6;
53:       PX.rect(ctx, left + 20 + i * 3, yy, W - 40 - i * 6, 1, rgba(p.roofD, .45));
54:     }
55:     // ridge cap
56:     PX.rect(ctx, left + W / 2 - 2, top + 2, 4, 10, p.roofD);
57:     PX.rect(ctx, left + W / 2 - 1, top + 2, 2, 7, p.roofL);
58: 
59:     // windows
60:     const winY = top + 50;
61:     for (const wx of [left + 18, left + W - 40]) {
62:       PX.rect(ctx, wx, winY, 22, 18, p.trim);
63:       PX.rect(ctx, wx + 2, winY + 2, 18, 14, '#87d8ef');
64:       PX.rect(ctx, wx + 2, winY + 2, 18, 5, '#bdf0ff');
65:       PX.rect(ctx, wx + 10, winY + 2, 2, 14, p.trim);
66:       PX.rect(ctx, wx + 2, winY + 8, 18, 1, p.trim);
67:       PX.rect(ctx, wx + 3, winY + 3, 4, 2, '#ffffff');
68:       // sill
69:       PX.rect(ctx, wx - 2, winY + 18, 26, 3, p.wallD);
70:     }
71: 
72:     // door
73:     const dx = left + 2 * T - 11, dy = top + H - 34;
74:     PX.rect(ctx, dx - 2, dy - 2, 26, 36, p.trim);
75:     PX.rect(ctx, dx, dy, 22, 32, '#5a3826');
76:     PX.rect(ctx, dx + 2, dy + 2, 18, 28, '#7a4f33');
77:     PX.rect(ctx, dx + 2, dy + 2, 18, 2, '#96694a');
78:     PX.rect(ctx, dx + 15, dy + 16, 2, 2, p.accent);
79:     PX.rect(ctx, dx - 4, dy + 32, 30, 3, p.wallD);
80:     PX.rect(ctx, dx + 4, dy + 6, 14, 8, rgba('#2a1a14', .5));
81: 
82:     // type-specific signage
83:     if (o.type === 'pokecenter') {
84:       PX.ell(ctx, left + 2 * T, top + 50, 9, 9, '#f5f5f5');
85:       PX.rect(ctx, left + 2 * T - 2, top + 39, 4, 22, '#e8445a');
86:       PX.rect(ctx, left + 2 * T - 9, top + 46, 18, 4, '#e8445a');
87:       PX.rect(ctx, left + 2 * T - 1, top + 41, 2, 18, '#ff8090');
