91:       PX.ell(ctx, left + 28, top + 10, 11, 6, '#cdd8de');
92:       PX.ell(ctx, left + 28, top + 9, 8, 4, '#eef8fb');
93:       PX.line(ctx, left + 28, top + 14, left + 28, top + 28, '#8a9aa4', 2);
94:       PX.rect(ctx, left + 25, top + 27, 7, 3, '#6c7c86');
