145:   function drawTree(ctx, o) {
146:     const cx = o.x * T + 16, by = o.y * T + 31;
147:     const big = o.type === 'old_tree';
148:     const scale = big ? 1.5 : 1;
149:     shadow(ctx, cx, by - 1, 15 * scale, 5 * scale, .3);
150:     // trunk
151:     PX.rect(ctx, cx - 4, by - 16, 8, 16, '#4a2e20');
152:     PX.rect(ctx, cx - 3, by - 16, 5, 14, '#6a442c');
153:     PX.rect(ctx, cx - 2, by - 15, 2, 9, '#8a5e3c');
154:     PX.rect(ctx, cx - 6, by - 2, 12, 3, '#3a2418');
155:     if (big) {
156:       PX.line(ctx, cx - 3, by - 12, cx - 12, by - 24, '#4a2e20', 4);
157:       PX.line(ctx, cx + 3, by - 13, cx + 12, by - 26, '#4a2e20', 4);
158:     }
159:     // canopy clusters
160:     const clusters = big
161:       ? [[0, -36, 20, 15], [-16, -26, 14, 12], [16, -27, 15, 12], [-8, -44, 13, 10], [10, -44, 12, 10], [0, -22, 17, 11]]
162:       : [[0, -27, 15, 13], [-9, -20, 11, 9], [9, -20, 11, 9], [0, -34, 11, 8]];
163:     for (const [dx, dy, rx, ry] of clusters) PX.ell(ctx, cx + dx, by + dy, rx + 2, ry + 2, '#0f3024');
164:     for (const [dx, dy, rx, ry] of clusters) PX.ell(ctx, cx + dx, by + dy, rx, ry, '#185039');
165:     // light tops
166:     for (const [dx, dy, rx, ry] of clusters) {
167:       PX.ell(ctx, cx + dx - 2, by + dy - 3, rx * .62, ry * .5, '#256b48');
168:       PX.ell(ctx, cx + dx - 4, by + dy - 5, rx * .34, ry * .26, '#3a8a59');
169:     }
170:     // leaf speckles
171:     for (let i = 0; i < 12; i++) {
172:       const r = seeded(o.x * 13 + i, o.y * 7, i * 91);
173:       const px = cx - 18 + r() * 36, py = by - (big ? 46 : 34) + r() * (big ? 34 : 26);
174:       PX.rect(ctx, px, py, 1, 1, i % 3 ? '#3f9a63' : '#7ac08a');
175:     }
176:   }
