    Art.drawParticles(ctx, state.particles, state.time, prof);

    ctx.restore();

    // grade / vignette
    Art.drawAmbient(ctx, m, canvas.width, canvas.height, state.time);
  }

  function init(g) {
    game = g;
    if (!playerStyle) refreshStyles();
    if (!state.particles.length || !map()) resetView();
    state.prevX = state.x; state.prevY = state.y; state.stepT = 1;
    UI.updateHud(map().name, game.party);
  }

  return { state, init, draw, update, step, interact, setMap, encounter };
})();

@font-face {
  font-family: 'PixelTitle';
  src: url('assets/fonts/PressStart2P.ttf') format('truetype');
  font-display: swap;
}
@font-face {
  font-family: 'PixelBody';
  src: url('assets/fonts/VT323.ttf') format('truetype');
  font-display: swap;
}

:root {
  --ink: #0a0b16;
  --panel: #101528;
  --panel2: #161d38;
  --gold: #f5c542;
  --gold2: #b8862b;
  --cyan: #67e8f9;
  --violet: #9b7bff;
  --rose: #ff7aa8;
  --text: #f4f1e8;
  --muted: #a9b2cf;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #06070d;
  color: var(--text);
  font-family: 'PixelBody', 'Courier New', monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(1100px 700px at 50% -10%, #1c2450 0%, transparent 60%),
    radial-gradient(900px 600px at 10% 110%, #2a0f2e 0%, transparent 60%),
    radial-gradient(900px 600px at 95% 100%, #062b33 0%, transparent 55%),
    #05060b;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(1px 1px at 20% 30%, rgba(255,255,255,.5) 50%, transparent 51%),
    radial-gradient(1px 1px at 70% 20%, rgba(255,255,255,.35) 50%, transparent 51%),
    radial-gradient(1px 1px at 40% 75%, rgba(255,255,255,.25) 50%, transparent 51%),
    radial-gradient(1px 1px at 85% 65%, rgba(255,255,255,.35) 50%, transparent 51%);
  background-size: 280px 280px, 340px 340px, 400px 400px, 310px 310px;
  opacity: .45;
}

#app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 10px;
  max-height: 100vh;
}

#gameframe {
  position: relative;
  width: min(96vw, calc((100vh - 58px) * 1.3333), 1100px);
  aspect-ratio: 4 / 3;
  border-radius: 14px;
  background: #06070d;
  overflow: hidden;
  box-shadow:
    0 0 0 3px #1b2444,
    0 0 0 6px #070912,
    0 0 0 8px #2c3766,
    0 18px 60px rgba(0,0,0,.8),
    0 0 90px rgba(103,232,249,.08);
}
#gameframe::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  border-radius: 14px;
  box-shadow:
    inset 0 0 78px rgba(3,6,20,.55),
    inset 0 0 0 1px rgba(170,205,255,.10);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0a0f1e;
}

#hint {
